import { Component, Element, Prop, h } from "@stencil/core";

/**
 * @since 0.0.15
 * @status experimental
 *
 */
@Component({
	tag: "hbr-card-horizontal",
	styleUrl: "hbr-card-horizontal.scss",
	shadow: true,
})
export class HbrCardHorizontal {
	cardHorizontal: HTMLElement;
	@Element() host: HTMLHbrCardHorizontalElement;

	/** Set to true to disable the horizontal card. */
	@Prop({ reflect: true }) disabled = false;

	/** Add a divider between the two side by side cards. */
	@Prop() divider = false;

	render() {
		return (
			<div
				ref={(el) => (this.cardHorizontal = el)}
				part="base"
				class={{
					"card-horizontal": true,
					"card-horizontal--is-disabled": this.disabled,
					"card-horizontal--middle-divider": this.divider,
				}}
			>
				<slot name="left" />
				<slot name="right" />
			</div>
		);
	}
}
